const ideaItem = $('Get Item (Webhook)').item.json[0] || $('Get Item (Webhook)').item.json;
const govData = $('Fetch Governance Registry').item.json.data;

if (!ideaItem) {
  throw new Error('CONTENT_ITEM_NOT_FOUND');
}

// Find agents
const agent1 = govData.agents.find(a => a.role_id === 'marketing_agent_1_viral_research_angle');
const agent2 = govData.agents.find(a => a.role_id === 'marketing_agent_2_social_caption_architect');
const agent3 = govData.agents.find(a => a.role_id === 'marketing_agent_3_image_prompt_architect');

const prompt = `You are an orchestration of 3 specialized AI Marketing Agents working in sequence.
You MUST respect the capabilities (MUST) and strictly avoid the prohibitions (MUST NOT) of each agent.
The governance rules are currently in DRAFT_METADATA_ONLY mode.

[AGENT 1: VIRAL RESEARCH ANGLE]
MUST: ${agent1.capability_boundary.must.join(', ')}
MUST NOT: ${agent1.capability_boundary.must_not.join(', ')}

[AGENT 2: SOCIAL CAPTION ARCHITECT]
MUST: ${agent2.capability_boundary.must.join(', ')}
MUST NOT: ${agent2.capability_boundary.must_not.join(', ')}

[AGENT 3: IMAGE PROMPT ARCHITECT]
MUST: ${agent3.capability_boundary.must.join(', ')}
MUST NOT: ${agent3.capability_boundary.must_not.join(', ')}

---
Idea Title: ${ideaItem.title}
Brief: ${ideaItem.brief || 'No brief provided.'}

IMPORTANT LANGUAGE INSTRUCTION:
- You MUST write the "agent_1_research_packet" and "agent_2_publish_ready_caption" entirely in Vietnamese (Tiếng Việt).
- The "agent_3_image_prompt" MUST remain in English.

Respond in STRICT JSON format, fulfilling the exact outputs required by each agent without crossing boundaries:
{
  "agent_1_research_packet": "Nội dung phân tích viral và pain points bằng Tiếng Việt...",
  "agent_2_publish_ready_caption": "Nội dung caption bài đăng bằng Tiếng Việt...",
  "agent_3_image_prompt": "A highly detailed image prompt in English..."
}
`;

return { json: { prompt: prompt, item: ideaItem, tenant_id: ideaItem.organization_id, organization_id: ideaItem.organization_id } };

const responseText = $input.item.json.choices[0].message.content || '{}';
const item = $('Format Prompt').item.json.item;
const tenant_id = $('Format Prompt').item.json.tenant_id;
let parsed = {};
try {
  parsed = JSON.parse(responseText);
} catch(e) {
  throw new Error('AI Response was not valid JSON');
}

return { 
  json: { 
    id: item.id, 
    organization_id: item.organization_id,
    tenant_id: tenant_id,
    textContent: {
      agent_1_research_packet: parsed.agent_1_research_packet,
      agent_2_publish_ready_caption: parsed.agent_2_publish_ready_caption,
      agent_3_image_prompt: parsed.agent_3_image_prompt
    },
    item: item
  } 
};

const textContent = $('Parse Text').item.json.textContent;
let imageUrl = "https://placehold.co/1024x1024?text=Image+Generation+Failed";
try {
  imageUrl = $('Extract Visual').item.json.payload.p_stage_payload.artifacts[0].content;
} catch(e) {}

return { 
  json: { 
    status: 'OK', 
    message: 'Content generated successfully',
    artifacts: {
      research: textContent.agent_1_research_packet,
      caption: textContent.agent_2_publish_ready_caption,
      image: imageUrl
    }
  } 
};

const textContent = $('Parse Text').item.json.textContent;
const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'idea',
  p_next_state: 'research_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_research',
  p_stage_payload: { artifacts: [{ artifact_key: 'res_' + $execution.id + '_' + item.id.replace(/-/g, '_'), artifact_type: 'viral_research_packet', content: textContent.agent_1_research_packet }] }
}}};

const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
let imageUrl = "https://placehold.co/1024x1024?text=Image+Generation+Failed";
if ($input.item.json.data && $input.item.json.data[0] && $input.item.json.data[0].url) {
  imageUrl = $input.item.json.data[0].url;
}
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'research_ready',
  p_next_state: 'visual_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_visual',
  p_stage_payload: { artifacts: [{ artifact_key: 'vis_' + $execution.id + '_' + item.id.replace(/-/g, '_'), artifact_type: 'visual_asset', content: imageUrl }] }
}}};

const textContent = $('Parse Text').item.json.textContent;
const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'visual_ready',
  p_next_state: 'caption_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_caption',
  p_stage_payload: { artifacts: [{ artifact_key: 'cap_' + $execution.id + '_' + item.id.replace(/-/g, '_'), artifact_type: 'caption_output', content: textContent.agent_2_publish_ready_caption }] }
}}};

const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'caption_ready',
  p_next_state: 'QA_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_qa_ready',
  p_stage_payload: {}
}}};
